ALTER TABLE tenants ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE users ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE employees ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE customers ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE sites ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE devices ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
CREATE TABLE IF NOT EXISTS permissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), key text UNIQUE NOT NULL, description text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS role_permissions (role text NOT NULL CHECK (role IN ('admin','operator','viewer')), permission_id uuid NOT NULL REFERENCES permissions(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(role,permission_id));
CREATE TABLE IF NOT EXISTS sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash text UNIQUE NOT NULL, csrf_token text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS sessions_token_hash_idx ON sessions(token_hash); CREATE INDEX IF NOT EXISTS sessions_expires_idx ON sessions(expires_at); CREATE INDEX IF NOT EXISTS role_permissions_role_idx ON role_permissions(role);
CREATE TABLE IF NOT EXISTS alarms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, device_id uuid REFERENCES devices(id) ON DELETE SET NULL, severity text NOT NULL CHECK (severity IN ('low','medium','high','critical')), status text NOT NULL DEFAULT 'open' CHECK (status IN ('open','acknowledged','resolved')), message text NOT NULL, triggered_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS alarms_tenant_idx ON alarms(tenant_id); CREATE INDEX IF NOT EXISTS alarms_device_idx ON alarms(device_id); CREATE INDEX IF NOT EXISTS alarms_status_idx ON alarms(status);
INSERT INTO permissions(key,description) VALUES ('employees:read','View employees'),('employees:write','Create and edit employees'),('employees:delete','Delete employees'),('customers:read','View customers'),('customers:write','Create and edit customers'),('customers:delete','Delete customers'),('sites:read','View sites'),('sites:write','Create and edit sites'),('sites:delete','Delete sites'),('devices:read','View devices'),('devices:write','Create and edit devices'),('devices:delete','Delete devices'),('alarms:read','View alarms'),('alarms:write','Create and edit alarms'),('alarms:delete','Delete alarms') ON CONFLICT (key) DO NOTHING;
INSERT INTO role_permissions(role,permission_id) SELECT 'admin',id FROM permissions ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role,permission_id) SELECT 'operator',id FROM permissions WHERE key NOT LIKE '%:delete' ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role,permission_id) SELECT 'viewer',id FROM permissions WHERE key LIKE '%:read' ON CONFLICT DO NOTHING;
